def generate_fibonacci_sequence(length, start1=0, start2=1):
    if length <= 0:
        return []
    elif length == 1:
        return [start1]
    elif length == 2:
        return [start1, start2]
    else:
        sequence = [start1, start2]
        for i in range(2, length):
            next_number = sequence[-1] + sequence[-2]
            sequence.append(next_number)
        return sequence
