from typing import List

def findTargetRange(nums: List[int], target: int) -> List[int]:
    # Helper function to find the leftmost index of the target
    def findLeft(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    # Helper function to find the rightmost index of the target
    def findRight(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    # Find the leftmost and rightmost indices of the target
    left_index = findLeft(nums, target)
    right_index = findRight(nums, target)

    # Check if the target is present in the array
    if left_index <= right_index:
        return [left_index, right_index]
    else:
        return [-1, -1]
```
This solution uses binary search to efficiently find the leftmost and rightmost indices of the target value in the sorted array. The `findLeft` function searches for the first occurrence of the target, and the `findRight` function searches for the last occurrence. If the target is found, the indices are returned; otherwise, `[-1, -1]` is returned.

