import sys

def build_tree(n):
    return [2**31 - 1] * (4 * n)

def update_tree(tree, n, i, s, t, x, pos):
    if s <= pos <= t:
        if s == t:
            tree[i] = x
        else:
            mid = (s + t) // 2
            update_tree(tree, n, 2 * i + 1, s, mid, x, pos)
            update_tree(tree, n, 2 * i + 2, mid + 1, t, x, pos)
            tree[i] = min(tree[2 * i + 1], tree[2 * i + 2])

def query_tree(tree, n, i, s, t, l, r):
    if r < s or t < l:
        return 2**31 - 1
    if l <= s and t <= r:
        return tree[i]
    mid = (s + t) // 2
    return min(query_tree(tree, n, 2 * i + 1, s, mid, l, r), query_tree(tree, n, 2 * i + 2, mid + 1, t, l, r))

