def can_place_star(grid, x, y, size):
    n, m = len(grid), len(grid[0])
    for i in range(x - size, x + size + 1):
        for j in range(y - size, y + size + 1):
            if not (0 <= i < n and 0 <= j < m):
                return False
            if i == x and j == y:
                continue
            if grid[i][j] == '*':
