import sys
from collections import defaultdict, deque

MOD = 10**9 + 9

def is_stable(cubes, x, y):
    if y == 0:
        return True
    for dx in [-1, 0, 1]:
        for dy in [-1, 0]:
            if (x + dx, y + dy) in cubes:
                return True
    return False

def simulate_disassembly(cubes):
    n = len(cubes)
    stack = []
    for i in range(n):
        x, y = cubes[i]
        if is_stable(cubes, x, y):
            stack.append(x)
        else:
            while stack and not is_stable(cubes, stack[-1], cubes[stack[-1]][1]):
                stack.pop()
            if stack:
                stack.append(x)
            else:
                return None
    return stack

def form_number(stack):
    number = 0
    for x in stack:
        number = (number * 10 + x) % MOD
    return number

