Here is a Python solution using Depth-First Search (DFS) to detect cycles in a directed graph:

```python
import sys

def has_cycle(graph, node, visited, rec_stack):
    visited[node] = True
    rec_stack[node] = True

    for neighbor in graph[node]:
        if not visited[neighbor]:
            if has_cycle(graph, neighbor, visited, rec_stack):
                return True
        elif rec_stack[neighbor]:
            return True

    rec_stack[node] = False
    return False

def detect_cycle(V, E, edges):
    graph = [[] for _ in range(V)]
    for s, t in edges:
        graph[s].append(t)

    visited = [False] * V
    rec_stack = [False] * V

    for node in range(V):
        if not visited[node]:
            if has_cycle(graph, node, visited, rec_stack):
                return 1

    return 0

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    V = int(data[0])
    E = int(data[1])

    edges = []
    for i in range(E):
        s = int(data[2 + 2 * i])
        t = int(data[3 + 2 * i])
        edges.append((s, t))

    print(detect_cycle(V, E, edges))
```

This program reads the input graph, constructs an adjacency list representation of the graph, and then uses DFS to detect cycles. If a cycle is found, it returns 1; otherwise, it returns 0.

