import sys

def read_input():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    nodes = {}
    index = 1
    for i in range(n):
        id = int(data[index])
        k = int(data[index + 1])
        children = list(map(int, data[index + 2:index + 2 + k]))
        nodes[id] = {'children': children, 'parent': None, 'depth': None, 'type': None}
        index += 2 + k
    return nodes

def find_root(nodes):
    for node in nodes:
        if not nodes[node]['children']:
            continue
        for child in nodes[node]['children']:
            if child in nodes and nodes[child]['parent'] is None:
                nodes[child]['parent'] = node
    root = None
    for node in nodes:
        if nodes[node]['parent'] is None:
            root = node
            break
    return root

def calculate_depths_and_types(nodes, root):
    stack = [(root, 0)]
    while stack:
        node, depth = stack.pop()
        nodes[node]['depth'] = depth
        if not nodes[node]['children']:
            nodes[node]['type'] = 'leaf'
        else:
            nodes[node]['type'] = 'internal node'
            for child in nodes[node]['children']:
                stack.append((child, depth + 1))

def print_output(nodes):
    for node in sorted(nodes):
        print(f"node {node}: parent = {nodes[node]['parent'] if nodes[node]['parent'] is not None else -1}, depth = {nodes[node]['depth']}, {nodes[node]['type']}, {nodes[node]['children']}")

def main():
    nodes = read_input()
    root = find_root(nodes)
    calculate_depths_and_types(nodes, root)
    print_output(nodes)

if __name__ == "__main__":
    main()
```

This program follows these steps:

1. **Read Input**: It reads the input from standard input, parses it, and stores the nodes in a dictionary where each node is represented by its ID and contains information about its children, parent, depth, and type.

2. **Find Root**: It identifies the root of the tree by finding a node that is not a child of any other node.

3. **Calculate Depths and Types**: It calculates the depth and type of each node using a depth-first search (DFS) approach.

4. **Print Output**: It prints the required information for each node in the specified format.

