import sys
from collections import defaultdict

MOD = 10**9 + 7

def dfs(node, color, graph, visited, dp):
    if (node, color) in dp:
        return dp[(node, color)]
    visited[node] = True
    count = 0
    for neighbor in graph[node]:
        if not visited[neighbor]:
            count += dfs(neighbor, 1 - color, graph, visited, dp)
    dp[(node, color)] = count
    return count

def count_paths(n, p, colors):
    graph = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if colors[i] != -1 and colors[j] != -1 and colors[i] != colors[j]:
                graph[i].append(j)
                graph[j].append(i)
    dp = {}
    visited = [False] * n
    count = 0
    for i in range(n):
        if not visited[i]:
            count += dfs(i, 0, graph, visited, dp)
    if p == 0:
        return count % MOD
    else:
        return (MOD - count) % MOD

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    p = int(data[1])
    colors = list(map(int, data[2:]))
    print(count_paths(n, p, colors))
