```python
import sys
from collections import defaultdict

def can_reach(x, y, target_x, target_y, actions):
    if actions[0] == 1 and x > target_x:
        return False
    if actions[1] == 1 and y < target_y:
        return False
    if actions[2] == 1 and x < target_x:
        return False
    if actions[3] == 1 and y > target_y:
        return False
    return True

def find_reachable_point(robots):
    if not robots:
        return 0

    # Collect all possible target points
    target_points = set()
    for x, y, actions in robots:
        for dx in range(-100000, 100001):
            for dy in range(-100000, 100001):
                if can_reach(x, y, x + dx, y + dy, actions):
                    target_points.add((x + dx, y + dy))

    # Check if there is a common point
    common_points = set()
    for point in target_points:
        if all(can_reach(x, y, point[0], point[1], actions) for x, y, actions in robots):
            common_points.add(point)

    if not common_points:
        return 0

    # Return the first common point
    return 1, common_points.pop()[0], common_points.pop()[1]

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    q = int(data[index])
    index += 1

    results = []

    for _ in range(q):
        n = int(data[index])
        index += 1
        robots = []

        for _ in range(n):
            x = int(data[index])
            y = int(data[index + 1])
            actions = [int(data[index + 2]), int(data[index + 3]), int(data[index + 4]), int(data[index + 5])]
            index += 6
            robots.append((x, y, actions))

        result = find_reachable_point(robots)
        results.append(result)

    for result in results:
        if result == 0:
            print(0)
        else:
            print(f"1 {result[1]} {result[2]}")

if __name__ == "__main__":
    main()
```

### Explanation:
1. **can_reach Function**: This function checks if a robot can reach a given target point \((target_x, target_y)\) based on its allowed actions.
2. **find_reachable_point Function**: This function finds a common point that all robots can reach. It iterates over all possible target points and checks if they are reachable by all robots.
3. **main Function**: This function reads the input, processes each query, and prints the results.

This code ensures that we correctly determine if there exists a point that all robots can reach and output the appropriate result.

