To solve this problem, we need to determine if a given table is "elegant" based on the criteria provided. Here's a step-by-step approach to achieve this:

1. **Identify Black Subrectangles**: A black subrectangle is one that contains no zeros. We need to find all such subrectangles.
2. **Identify Nice Subrectangles**: A nice subrectangle is a black subrectangle that is not contained within any other black subrectangle.
3. **Check for Intersections**: Ensure that no two nice subrectangles intersect.
4. **Determine if the Table is Elegant**: If there are no two nice intersecting subrectangles, the table is elegant.

Here's the Python code to implement this logic:

```python
def is_black_subrectangle(table, x1, y1, x2, y2):
    for i in range(x1, x2 + 1):
        for j in range(y1, y2 + 1):
            if table[i][j] == '0':
                return False
    return True

def is_nice_subrectangle(table, x1, y1, x2, y2, black_subrectangles):
    for bx1, by1, bx2, by2 in black_subrectangles:
        if x1 >= bx1 and y1 >= by1 and x2 <= bx2 and y2 <= by2:
            return False
    return True

def find_nice_subrectangles(table):
    n, m = len(table), len(table[0])
    black_subrectangles = []
    nice_subrectangles = []

    for x1 in range(n):
        for y1 in range(m):
            for x2 in range(x1, n):
                for y2 in range(y1, m):
                    if is_black_subrectangle(table, x1, y1, x2, y2):
                        black_subrectangles.append((x1, y1, x2, y2))

    for bx1, by1, bx2, by2 in black_subrectangles:
        if is_nice_subrectangle(table, bx1, by1, bx2, by2, black_subrectangles):
            nice_subrectangles.append((bx1, by1, bx2, by2))

    return nice_subrectangles

def is_elegant(table):
    nice_subrectangles = find_nice_subrectangles(table)
    n, m = len(table), len(table[0])

    for i in range(n):
        for j in range(m):
            for x1, y1, x2, y2 in nice_subrectangles:
                if x1 <= i <= x2 and y1 <= j <= y2:
                    for x3, y3, x4, y4 in nice_subrectangles:
                        if x3 != x1 or y3 != y1 or x4 != x2 or y4 != y2:
                            if x3 <= i <= x4 and y3 <= j <= y4:
                                return False
    return True

